CARDIO.register({"item":"d111","meta":{"num":"d111","label":"111","spe":"dermato","short":"Acné, rosacée, DS","title":"Dermatoses faciales : acné, rosacée, dermatite séborrhéique","section":"D","chapter":1,"pages":"33-53","sdd":[{"num":78,"label":"Acné"},{"num":83,"label":"Cicatrice anormale"},{"num":139,"label":"Anomalies palpébrales"}]},"objectives":[{"id":"d111-obj-01","rank":"A","rubric":"Définition","title":"Définition de l'acné","desc":"Savoir que l'acné est une maladie inflammatoire du follicule pilo-sébacé"},{"id":"d111-obj-02","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître les mécanismes de l'acné","desc":"Séborrhée/kératinisation infundibulaire du follicule pilo-sébacé/rôle de P. acnes/hyperandrogénie périphérique avec taux normaux d'androgènes circulants"},{"id":"d111-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître les éléments cliniques permettant de diagnostiquer une acné","desc":"Séborrhée, lésions rétentionnelles (comédons ouverts et fermés), lésions inflammatoires (papulo-pustules)/cicatrices"},{"id":"d111-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Savoir classer cliniquement une acné","desc":"Trois formes cliniques principales (acné mixte, acné rétentionnelle et acné nodulaire)"},{"id":"d111-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Connaître deux formes cliniques d'acné","desc":"Acné néonatale, acné liée aux endocrinopathies"},{"id":"d111-obj-06","rank":"B","rubric":"Contenu multimédia","title":"Savoir reconnaître les différentes formes cliniques d'acné","desc":"Photographies d'acné rétentionnelle, papulo-pustuleuse et nodulaire"},{"id":"d111-obj-07","rank":"B","rubric":"Diagnostic positif","title":"Connaître deux diagnostics différentiels d'acné","desc":"Folliculite infectieuse, rosacée"},{"id":"d111-obj-08","rank":"B","rubric":"Prise en charge","title":"Connaître les traitements systémiques et topiques de l'acné","desc":""},{"id":"d111-obj-09","rank":"B","rubric":"Prise en charge","title":"Connaître les recommandations en termes de contraception dans l'acné","desc":""},{"id":"d111-obj-10","rank":"B","rubric":"Prise en charge","title":"Connaître les conseils hygiéno-diététiques à prodiguer à un patient acnéique","desc":""},{"id":"d111-obj-11","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une rosacée","desc":"Connaître les éléments cliniques permettant de diagnostiquer une rosacée dans sa forme vasculaire, papulo-pustuleuse et hypertrophique"},{"id":"d111-obj-12","rank":"A","rubric":"Contenu multimédia","title":"Savoir reconnaître une rosacée","desc":"Photographies des trois formes de rosacée"},{"id":"d111-obj-13","rank":"B","rubric":"Éléments physiopathologiques","title":"Physiopathologie de la dermatite séborrhéique","desc":"Malasseziose"},{"id":"d111-obj-14","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une dermatite séborrhéique","desc":"Connaître les éléments cliniques positifs qui permettent de poser le diagnostic de dermite séborrhéique selon l'âge, la topographie des lésions et le terrain"},{"id":"d111-obj-15","rank":"A","rubric":"Contenu multimédia","title":"Savoir reconnaître une dermite séborrhéique","desc":"Photographie d'une dermatite séborrhéique"},{"id":"d111-obj-16","rank":"B","rubric":"Diagnostic positif","title":"Connaître les principaux diagnostics différentiels","desc":"Psoriasis et dermatite atopique"}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d111-qroc-001","type":"QROC","rank":"A","objective":"d111-obj-01","tags":["définition"],"difficulty":1,"question":"L'acné est une dermatose inflammatoire chronique de quelle structure cutanée ?","answer":"Du follicule pilo-sébacé","accept":["follicule pilo-sébacé","follicule pilosébacé"],"keywords":["pilo","sébac"],"explanation":"L'acné est une dermatose inflammatoire chronique du follicule pilo-sébacé, le plus souvent chez l'adolescent.","src":"p. 34, 45"},{"id":"d111-qroc-002","type":"QROC","rank":"A","objective":"d111-obj-01","tags":["définition","épidémiologie"],"difficulty":1,"question":"À quelle période de la vie l'acné survient-elle le plus souvent ?","answer":"À l'adolescence","accept":["adolescence","adolescent","puberté"],"keywords":["adolesc"],"explanation":"L'acné est le plus souvent une maladie de l'adolescence. L'acné mixte juvénile, forme la plus commune, débute à la puberté (en moyenne 12 ans chez les filles, 14 ans chez les garçons).","src":"p. 37, 45"},{"id":"d111-qroc-003","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["diagnostic"],"difficulty":1,"question":"Sur quel type d'examen repose le diagnostic positif de l'acné ?","answer":"L'examen clinique","accept":["clinique","diagnostic clinique","examen clinique"],"keywords":["clinique"],"explanation":"Le diagnostic d'acné est clinique : il repose sur la séborrhée et sur les lésions élémentaires rétentionnelles et inflammatoires.","src":"p. 35"},{"id":"d111-qroc-004","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Quel aspect de la peau définit la séborrhée de l'acné ?","answer":"Une peau grasse et luisante","accept":["peau grasse et luisante","peau grasse","grasse et luisante","luisante"],"keywords":["gras","luisant"],"explanation":"La séborrhée (peau grasse et luisante) est constante dans l'acné ; elle touche la partie centrale du visage et la région thoracique supérieure.","src":"p. 35"},{"id":"d111-qroc-005","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelles sont les deux lésions rétentionnelles de l'acné ?","answer":"Comédons fermés (microkystes) et comédons ouverts","accept":["comédons ouverts et fermés","comédons fermés et ouverts","comédon ouvert et comédon fermé","comédon fermé et comédon ouvert","microkystes et comédons ouverts","comédons ouverts et microkystes"],"keywords":["ouvert","ferm"],"explanation":"Les comédons fermés (ou microkystes) et les comédons ouverts (« points noirs ») sont les lésions rétentionnelles ; les autres lésions de l'acné sont inflammatoires (papules, pustules, nodules).","src":"p. 35"},{"id":"d111-qroc-006","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Quel autre nom désigne les comédons fermés ?","answer":"Les microkystes","accept":["microkystes","microkyste","micro-kystes","micro-kyste"],"keywords":["microkyst"],"explanation":"Les comédons fermés (microkystes) sont de petites papules de 2 à 3 mm, de la couleur de la peau, parfois plus palpables que visibles ; ils peuvent s'enflammer.","src":"p. 35"},{"id":"d111-qroc-007","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"À quelle lésion élémentaire correspondent les « points noirs » ?","answer":"Aux comédons ouverts","accept":["comédon ouvert","comédons ouverts"],"keywords":["comédon","ouvert"],"explanation":"Le comédon ouvert (1 à 3 mm) résulte de l'accumulation de kératinocytes oxydés dans l'orifice dilaté du canal infundibulaire ; il peut s'expulser spontanément ou s'enflammer.","src":"p. 35"},{"id":"d111-qroc-008","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelles sont les deux lésions inflammatoires superficielles de l'acné ?","answer":"Les papules et les pustules","accept":["papules et pustules","papule et pustule","papulo-pustules","papulopustules"],"keywords":["papul","pustul"],"explanation":"Les papules (< 10 mm, rouges, fermes) et les pustules (contenu purulent jaune) sont les lésions inflammatoires superficielles ; les nodules sont les lésions inflammatoires profondes.","src":"p. 36"},{"id":"d111-qroc-009","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelle est la lésion inflammatoire profonde de l'acné ?","answer":"Le nodule","accept":["nodule","nodules"],"keywords":["nodul"],"explanation":"Le nodule (> 10 mm) peut évoluer vers l'abcédation et la formation de cicatrices ; sa rupture dans le derme profond donne des sinus, nodules allongés très douloureux.","src":"p. 36"},{"id":"d111-qroc-010","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"question":"Dans l'acné, quel seuil de taille sépare les papules des nodules ?","answer":"10 mm","accept":["10 mm","10mm","1 cm"],"keywords":["10"],"explanation":"Les papules mesurent moins de 10 mm ; les nodules mesurent plus de 10 mm.","src":"p. 36"},{"id":"d111-qroc-011","type":"QROC","rank":"A","objective":"d111-obj-03","tags":["clinique","complications"],"difficulty":1,"question":"Quelle séquelle est fréquente après des lésions inflammatoires d'acné qui durent depuis longtemps ?","answer":"Les cicatrices","accept":["cicatrice","cicatrices","cicatrices déprimées"],"keywords":["cicatri"],"explanation":"Les cicatrices, fréquentes, sont surtout secondaires aux lésions inflammatoires prolongées ; elles peuvent être déprimées, et hyperpigmentées sur peau foncée.","src":"p. 37"},{"id":"d111-qroc-012","type":"QROC","rank":"B","objective":"d111-obj-02","tags":["physiopathologie"],"difficulty":2,"question":"L'acné survient malgré des androgènes circulants à taux normaux : de quel type d'hyperandrogénie s'agit-il ?","answer":"Hyperandrogénie périphérique","accept":["hyperandrogénie périphérique","périphérique","hypersensibilité des récepteurs aux androgènes"],"keywords":["périph"],"explanation":"L'acné résulte d'une sensibilité particulière des récepteurs aux androgènes des sébocytes et des kératinocytes (hyperandrogénie périphérique), avec des androgènes circulants à taux normaux.","src":"p. 34"},{"id":"d111-qroc-013","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":1,"question":"Quelle classe d'antibiotiques par voie générale est le traitement de choix de l'acné ?","answer":"Les cyclines","accept":["cyclines","cycline","doxycycline","lymécycline"],"keywords":["cycline"],"explanation":"Les cyclines (doxycycline, lymécycline) sont l'antibiotique général de choix, utilisées en moyenne 3 mois, toujours associées à un traitement local et jamais à un antibiotique topique.","src":"p. 41"},{"id":"d111-qroc-014","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":2,"question":"Quelle est la place de l'isotrétinoïne dans le traitement de l'acné, hors formes très sévères ?","answer":"2e intention, après échec de 3 mois de cyclines","accept":["deuxième intention","2e intention","après échec de 3 mois de cyclines","après 3 mois de cyclines"],"keywords":["échec","cycline"],"explanation":"L'isotrétinoïne est un traitement de deuxième intention, prescrit après échec de 3 mois de cyclines ; dans les formes très sévères, elle peut être donnée plus tôt.","src":"p. 42"},{"id":"d111-qroc-015","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":2,"question":"Quelle dose cumulée d'isotrétinoïne vise-t-on au cours d'un traitement de l'acné ?","answer":"120 à 150 mg/kg","accept":["120 à 150 mg/kg","120-150 mg/kg","120 à 150","120-150"],"keywords":["120","150"],"explanation":"La dose moyenne est de 0,5 mg/kg/jour jusqu'à une dose cumulée de 120 à 150 mg/kg, obtenue en 9 à 12 mois en moyenne ; 0,2 à 0,3 mg/kg/jour suffisent dans les formes rétentionnelles.","src":"p. 41"},{"id":"d111-qroc-016","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement","pièges"],"difficulty":1,"question":"Quel risque majeur de l'isotrétinoïne impose une contraception efficace chez la femme en âge de procréer ?","answer":"Le risque tératogène","accept":["tératogène","tératogénicité","effet tératogène"],"keywords":["tératog"],"explanation":"L'isotrétinoïne est tératogène : contraception efficace, tests de grossesse mensuels, information détaillée et consentement signé de la patiente sont indispensables.","src":"p. 41-42"},{"id":"d111-qroc-017","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement","suivi"],"difficulty":2,"question":"Quels délais de contraception faut-il respecter avant le début et après l'arrêt de l'isotrétinoïne ?","answer":"1 mois avant et 1 mois après l'arrêt","accept":["1 mois avant et 1 mois après","un mois avant et un mois après","1 mois avant et après","un mois avant et après"],"keywords":["1 mois","avant","après"],"explanation":"La contraception commence 1 mois avant le traitement, dure tout le traitement et se poursuit 1 mois après l'arrêt ; le dernier test de grossesse est réalisé 5 semaines après l'arrêt.","src":"p. 42"},{"id":"d111-qroc-018","type":"QROC","rank":"B","objective":"d111-obj-08","tags":["traitement","pièges"],"difficulty":2,"question":"Quel risque justifie la contre-indication de l'association isotrétinoïne et cyclines ?","answer":"L'hypertension intracrânienne","accept":["hypertension intracrânienne","htic","hypertension intra-crânienne"],"keywords":["intracran"],"explanation":"L'association de l'isotrétinoïne et des cyclines est contre-indiquée en raison du risque d'hypertension intracrânienne.","src":"p. 42"},{"id":"d111-qroc-019","type":"QROC","rank":"B","objective":"d111-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel progestatif est recommandé en première intention pour la contraception œstroprogestative d'une femme acnéique ?","answer":"Le lévonorgestrel (2e génération)","accept":["lévonorgestrel","lévonorgestrel 2e génération"],"keywords":["lévonorgestrel"],"explanation":"On privilégie les progestatifs à faible activité androgénique : lévonorgestrel en première intention, norgestimate en deuxième intention.","src":"p. 42"},{"id":"d111-qroc-020","type":"QROC","rank":"B","objective":"d111-obj-10","tags":["traitement"],"difficulty":1,"question":"Quel régime alimentaire faut-il conseiller à un patient acnéique ?","answer":"Aucun : pas de régime à suivre","accept":["aucun","aucun régime","pas de régime","pas de régime alimentaire"],"keywords":["aucun"],"explanation":"Il n'y a pas de régime alimentaire à suivre dans l'acné. Les conseils portent sur l'application du traitement, l'hydratation, le soleil et la patience (résultat appréciable après 2 à 3 mois).","src":"p. 45"},{"id":"d111-qroc-021","type":"QROC","rank":"B","objective":"d111-obj-10","tags":["traitement"],"difficulty":1,"question":"À quel moment de la journée applique-t-on les traitements locaux de l'acné (rétinoïdes, peroxyde de benzoyle) ?","answer":"Le soir","accept":["soir","le soir","en soirée"],"keywords":["soir"],"explanation":"Les ultraviolets détruisent ces produits et certains sont photosensibilisants : on les applique le soir, sur tout le visage et pas seulement sur les lésions.","src":"p. 40, 45"},{"id":"d111-qroc-022","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["épidémiologie"],"difficulty":1,"question":"Entre quels âges se situe le pic de fréquence de la rosacée ?","answer":"Entre 40 et 50 ans","accept":["40 et 50 ans","40 à 50 ans","40-50 ans"],"keywords":["40","50"],"explanation":"La rosacée touche surtout l'adulte après 20 ans, avec un pic de fréquence entre 40 et 50 ans, une prédominance féminine (ratio F/H environ 2) et un terrain de peau, yeux et cheveux clairs.","src":"p. 46"},{"id":"d111-qroc-023","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["clinique"],"difficulty":1,"question":"Quelles sont les trois formes cliniques de la rosacée ?","answer":"Vasculaire, papulo-pustuleuse et hypertrophique","accept":["vasculaire, papulo-pustuleuse, rhinophyma","érythémato-télangiectasique, papulo-pustuleuse, hypertrophique"],"keywords":["vasculaire","papulo","hypertroph"],"explanation":"Forme vasculaire (bouffées vasomotrices, érythème permanent avec télangiectasies), forme papulo-pustuleuse (la plus caractéristique) et forme hypertrophique (rhinophyma) ; le passage par ces formes successives n'est pas obligatoire.","src":"p. 46-48"},{"id":"d111-qroc-024","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["clinique"],"difficulty":1,"question":"Comment appelle-t-on les poussées paroxystiques de rougeur du visage et du cou, avec sensation de chaleur, durant quelques minutes ?","answer":"Bouffées vasomotrices (flushes)","accept":["bouffées vasomotrices","bouffée vasomotrice","flush","flushes"],"keywords":["vasomot"],"explanation":"Les bouffées vasomotrices sont la composante vasculaire paroxystique de la rosacée ; elles sont déclenchées par les changements de température, l'alcool et les boissons ou aliments chauds ou épicés.","src":"p. 46"},{"id":"d111-qroc-025","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["clinique"],"difficulty":1,"question":"Comment appelle-t-on l'érythème facial permanent associé à des télangiectasies dans la rosacée ?","answer":"La couperose","accept":["couperose","rosacée érythémato-télangiectasique","érythémato-télangiectasique"],"keywords":["couperose"],"explanation":"La rosacée érythémato-télangiectasique associe un érythème permanent à des télangiectasies (couperose) des joues, du nez, du menton et de la partie médiane du front ; des bouffées vasomotrices peuvent s'y associer.","src":"p. 47"},{"id":"d111-qroc-026","type":"QROC","rank":"A","objective":"d111-obj-12","tags":["clinique"],"difficulty":1,"question":"Quelle forme clinique est la plus caractéristique de la rosacée ?","answer":"La forme papulo-pustuleuse","accept":["papulo-pustuleuse","papulopustuleuse"],"keywords":["papulo"],"explanation":"Des papules inflammatoires et des pustules apparaissent sur un fond d'érythème permanent, avec la même topographie que la forme vasculaire.","src":"p. 47"},{"id":"d111-qroc-027","type":"QROC","rank":"A","objective":"d111-obj-12","tags":["clinique"],"difficulty":1,"question":"Comment appelle-t-on la forme hypertrophique de la rosacée, où le nez devient volumineux, rouge et fibreux ?","answer":"Le rhinophyma","accept":["rhinophyma","rhinophyme"],"keywords":["rhinophym"],"explanation":"Le rhinophyma donne au nez l'aspect classique de « trogne », avec des orifices folliculaires dilatés, sans qu'un alcoolisme soit en cause.","src":"p. 48"},{"id":"d111-qroc-028","type":"QROC","rank":"A","objective":"d111-obj-12","tags":["clinique","épidémiologie"],"difficulty":1,"question":"Quel sexe est principalement touché par le rhinophyma ?","answer":"Les hommes (plus de 95 % des cas)","accept":["homme","hommes","sexe masculin","masculin"],"keywords":["homme"],"explanation":"Plus de 95 % des rhinophymas surviennent chez l'homme, généralement après 50 ans, alors que la rosacée dans son ensemble prédomine chez la femme.","src":"p. 46, 48"},{"id":"d111-qroc-029","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelles lésions élémentaires, présentes dans l'acné, sont absentes dans la rosacée ?","answer":"Les comédons (lésions rétentionnelles)","accept":["comédon","lésions rétentionnelles","microkystes","signes rétentionnels"],"keywords":["comédon"],"explanation":"L'acné se distingue de la rosacée par les signes rétentionnels (comédons, microkystes), la séborrhée, l'absence de bouffées vasomotrices et un terrain plus jeune.","src":"p. 48"},{"id":"d111-qroc-030","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["diagnostic"],"difficulty":2,"question":"Comment appelle-t-on l'association, chez un même patient, d'une rosacée et d'une dermatite séborrhéique ?","answer":"Dermatose mixte du visage","accept":["dermatose mixte","dermatose mixte du visage"],"keywords":["mixte"],"explanation":"Une rosacée et une dermatite séborrhéique peuvent coexister chez un même individu : c'est la « dermatose mixte du visage ».","src":"p. 48"},{"id":"d111-qroc-031","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quels examens complémentaires faut-il pour diagnostiquer une rosacée ?","answer":"Aucun : le diagnostic est clinique","accept":["aucun","aucun examen","pas d'examen","diagnostic clinique","clinique"],"keywords":["aucun"],"explanation":"La rosacée est une rougeur centrofaciale chronique de l'adulte avec bouffées vasomotrices ; son diagnostic est clinique, sans examen complémentaire.","src":"p. 46, 50"},{"id":"d111-qroc-032","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["traitement","pièges"],"difficulty":1,"question":"Quelle classe thérapeutique est contre-indiquée dans la rosacée ?","answer":"Les dermocorticoïdes","accept":["dermocorticoïdes","dermocorticoïde","corticoïdes locaux","corticoïdes topiques"],"keywords":["corticoïd"],"explanation":"Les dermocorticoïdes sont contre-indiqués dans la rosacée.","src":"p. 50"},{"id":"d111-qroc-033","type":"QROC","rank":"A","objective":"d111-obj-11","tags":["complications"],"difficulty":1,"question":"Quel organe, autre que la peau, peut être atteint au cours de la rosacée ?","answer":"L'œil (atteinte oculaire)","accept":["œil","oeil","yeux","oculaire","atteinte oculaire"],"keywords":[],"explanation":"L'atteinte oculaire est possible et fréquente : sécheresse, conjonctivite, blépharite, voire kératite (30 à 50 % des patients ont des signes subjectifs).","src":"p. 49-50"},{"id":"d111-qroc-034","type":"QROC","rank":"A","objective":"d111-obj-13","tags":["étiologie","physiopathologie"],"difficulty":1,"question":"Quelle levure est suspectée de jouer un rôle dans la dermatite séborrhéique ?","answer":"Malassezia","accept":["malassezia","malassezia furfur"],"keywords":["malassez"],"explanation":"Le rôle de Malassezia est suspecté (localisation sur les zones où la levure est la plus dense, efficacité des antifongiques) ; la dermatite séborrhéique n'est pas contagieuse.","src":"p. 50, 53"},{"id":"d111-qroc-035","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quel examen complémentaire faut-il pour poser le diagnostic de dermatite séborrhéique ?","answer":"Aucun : le diagnostic est clinique","accept":["aucun","aucun examen","pas de biopsie","diagnostic clinique","examen clinique"],"keywords":["aucun"],"explanation":"Le diagnostic repose sur l'examen clinique, sans prélèvement biopsique ni examen biologique ou mycologique.","src":"p. 51"},{"id":"d111-qroc-036","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["épidémiologie","clinique"],"difficulty":1,"question":"Quelle population est la plus touchée par la dermatite séborrhéique de l'adulte ?","answer":"Les hommes jeunes (18 à 40 ans)","accept":["hommes jeunes","homme jeune","18 à 40 ans","18-40 ans"],"keywords":["homme","jeune"],"explanation":"La dermatite séborrhéique de l'adulte touche le plus souvent l'homme jeune de 18 à 40 ans ; elle est aggravée par le stress émotionnel et s'améliore spontanément en été.","src":"p. 51"},{"id":"d111-qroc-037","type":"QROC","rank":"A","objective":"d111-obj-15","tags":["diagnostic","clinique"],"difficulty":2,"question":"Un homme de 30 ans, en bonne santé, présente des plaques érythémateuses recouvertes de petites squames grasses des sillons nasogéniens, des sourcils et de la glabelle, aggravées en période de stress. Quel est le diagnostic le plus probable ?","answer":"Dermatite séborrhéique","accept":["dermatite séborrhéique","dermite séborrhéique","dermatite séborrhéique de l'adulte"],"keywords":["séborrh"],"explanation":"Plaques érythémateuses à squames grasses des zones séborrhéiques du visage chez un homme jeune, aggravées par le stress : dermatite séborrhéique, au diagnostic clinique.","src":"p. 51"},{"id":"d111-qroc-038","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["clinique"],"difficulty":2,"question":"Comment appelle-t-on la forme sévère de dermatite séborrhéique du cuir chevelu, en « casque » engainant les touffes de cheveux ?","answer":"Le pityriasis amiantacé","accept":["pityriasis amiantacé","amiantacé"],"keywords":["amiantac"],"explanation":"Les formes peu sévères du cuir chevelu (les plus fréquentes) donnent de petites squames non adhérentes, avec un état pelliculaire (pityriasis capitis) ; la forme sévère est le pityriasis amiantacé.","src":"p. 51"},{"id":"d111-qroc-039","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Comment appelle-t-on les croûtes jaunes du cuir chevelu du nourrisson atteint de dermatite séborrhéique ?","answer":"Les croûtes de lait","accept":["croûtes de lait","croûte de lait"],"keywords":["croûte","lait"],"explanation":"Chez le nouveau-né en bonne santé, la dermatite séborrhéique débute après la 2e semaine de vie et réalise des croûtes jaunes du cuir chevelu (croûtes de lait) et du visage.","src":"p. 52"},{"id":"d111-qroc-040","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Comment s'appelle la forme étendue de dermatite séborrhéique du nourrisson, réalisant une érythrodermie ?","answer":"L'érythrodermie de Leiner-Moussous","accept":["leiner-moussous","leiner"],"keywords":["leiner"],"explanation":"L'érythrodermie de Leiner-Moussous est la forme étendue de la dermatite séborrhéique du nourrisson ; son évolution est le plus souvent spontanément favorable.","src":"p. 52"},{"id":"d111-qroc-041","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Que faut-il proposer devant une dermatite séborrhéique grave et/ou chronique ?","answer":"Un test de dépistage du VIH","accept":["dépistage du vih","dépistage vih","test vih","sérologie vih","vih"],"keywords":["vih"],"explanation":"La dermatite séborrhéique est fréquente au cours de l'infection par le VIH (40 % des séropositifs, jusqu'à 80 % au stade Sida), où elle est profuse et résistante au traitement : une forme grave ou chronique justifie un dépistage.","src":"p. 52-53"},{"id":"d111-qroc-042","type":"QROC","rank":"A","objective":"d111-obj-14","tags":["traitement"],"difficulty":1,"question":"Quel type de traitement est essentiellement utilisé dans la dermatite séborrhéique ?","answer":"Un traitement local (antifongique)","accept":["traitement local","local","topique","antifongique local","antifongiques locaux"],"keywords":["local"],"explanation":"Le traitement est essentiellement local (antifongique). La maladie est chronique et évolue par poussées, parfois favorisées par le stress.","src":"p. 53"},{"id":"d111-qcm-101","type":"QRM","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":1,"stem":"Une adolescente de 15 ans consulte pour une acné du visage. Parmi les lésions élémentaires suivantes, lesquelles sont des lésions rétentionnelles ?","options":[{"t":"Les papules","ok":false,"why":"Lésions inflammatoires superficielles (moins de 10 mm), généralement issues d'une lésion rétentionnelle."},{"t":"Les comédons ouverts","ok":true,"why":"Lésions rétentionnelles de 1 à 3 mm, dues à l'accumulation de kératinocytes oxydés dans l'orifice dilaté du follicule."},{"t":"Les nodules","ok":false,"why":"Lésions inflammatoires profondes, de plus de 10 mm."},{"t":"Les microkystes","ok":true,"why":"Petites papules de 2 à 3 mm, de la couleur de la peau, liées à l'accumulation de sébum et de kératine dans un canal folliculaire obstrué."},{"t":"Les pustules","ok":false,"why":"Lésions inflammatoires superficielles, avec un contenu purulent jaune."}],"explanation":"L'acné associe des lésions rétentionnelles (comédons ouverts et fermés) à des lésions inflammatoires (papules, pustules, nodules).","src":"p. 35-36"},{"id":"d111-qcm-102","type":"QRM","rank":"A","objective":"d111-obj-01","tags":["définition","diagnostic"],"difficulty":1,"stem":"Concernant la définition et le diagnostic de l'acné, quelles propositions sont exactes ?","options":[{"t":"C'est une dermatose inflammatoire chronique du follicule pilo-sébacé","ok":true,"why":"C'est la définition de l'acné."},{"t":"La séborrhée est inconstante, surtout chez l'adolescent","ok":false,"why":"La séborrhée (peau grasse et luisante) est constante."},{"t":"Le diagnostic est clinique","ok":true,"why":"Il repose sur la séborrhée et les lésions rétentionnelles et inflammatoires."},{"t":"Les cicatrices sont exceptionnelles après des lésions inflammatoires","ok":false,"why":"Les cicatrices sont fréquentes, surtout après des lésions inflammatoires prolongées."},{"t":"Elle survient le plus souvent à l'adolescence","ok":true,"why":"L'acné est le plus souvent une maladie de l'adolescence."}],"explanation":"Acné : dermatose inflammatoire chronique du follicule pilo-sébacé, le plus souvent de l'adolescent, au diagnostic clinique, avec une séborrhée constante et des cicatrices fréquentes.","src":"p. 35, 37, 45"},{"id":"d111-qru-101","type":"QRU","rank":"A","objective":"d111-obj-03","tags":["clinique"],"difficulty":2,"stem":"Un adolescent de 16 ans présente sur la joue une lésion inflammatoire profonde de 12 mm de diamètre, très douloureuse. Quelle est la lésion élémentaire ?","options":[{"t":"Une papule","ok":false,"why":"Une papule mesure moins de 10 mm."},{"t":"Un nodule","ok":true,"why":"Lésion inflammatoire profonde de plus de 10 mm ; elle peut s'abcéder et laisser des cicatrices."},{"t":"Une pustule","ok":false,"why":"Lésion superficielle dont le sommet contient un pus jaune."},{"t":"Un comédon fermé (microkyste)","ok":false,"why":"Lésion rétentionnelle de 2 à 3 mm, de la couleur de la peau."},{"t":"Un comédon ouvert","ok":false,"why":"Lésion rétentionnelle de 1 à 3 mm (« point noir »)."}],"explanation":"Une lésion inflammatoire profonde de plus de 10 mm est un nodule.","src":"p. 35-36"},{"id":"d111-qcm-103","type":"QRM","rank":"B","objective":"d111-obj-02","tags":["physiopathologie"],"difficulty":2,"stem":"À propos des mécanismes de l'acné (séborrhée, kératinisation, flore microbienne), quelles propositions sont exactes ?","options":[{"t":"La sécrétion de sébum est déclenchée principalement par la dihydrotestostérone","ok":true,"why":"Elle est produite dans les sébocytes par la 5α-réductase de type I à partir de la testostérone libre."},{"t":"Les androgènes circulants sont présents à des taux normaux","ok":true,"why":"L'acné résulte d'une sensibilité particulière des récepteurs aux androgènes (hyperandrogénie périphérique)."},{"t":"Cutibacterium acnes est une bactérie à Gram négatif","ok":false,"why":"C'est une bactérie à Gram positif, dominante dans la flore anaérobie des follicules sébacés."},{"t":"Le comédon résulte d'une hyperprolifération des kératinocytes du follicule","ok":true,"why":"Associée à des anomalies de différenciation qui empêchent leur élimination normale du canal infundibulaire."},{"t":"L'acné est une maladie infectieuse due à Cutibacterium acnes","ok":false,"why":"C'est une maladie inflammatoire du follicule pilo-sébacé, pas une maladie infectieuse."}],"explanation":"Séborrhée (dihydrotestostérone, récepteurs sensibles), kératinisation infundibulaire (comédon) et inflammation liée à Cutibacterium acnes : l'acné n'est pas une infection.","src":"p. 34-35"},{"id":"d111-qcm-104","type":"QRM","rank":"B","objective":"d111-obj-04","tags":["clinique"],"difficulty":1,"stem":"Concernant les formes cliniques de l'acné, quelles propositions sont exactes ?","options":[{"t":"L'acné mixte juvénile débute en moyenne à 14 ans chez les filles et à 12 ans chez les garçons","ok":false,"why":"C'est l'inverse : 12 ans chez les filles, 14 ans chez les garçons."},{"t":"L'acné mixte juvénile est la forme la plus commune","ok":true,"why":"Elle survient à la puberté et peut s'étendre au tronc."},{"t":"L'acné rétentionnelle est la forme la plus fréquente de l'acné débutante","ok":true,"why":"Elle associe essentiellement des microkystes et des comédons ouverts du visage."},{"t":"Une acné est dite sévère en présence de nombreux comédons fermés","ok":false,"why":"L'acné est sévère en présence de nodules."},{"t":"L'acné nodulaire peut évoluer vers des abcès ou des sinus et laisser des cicatrices souvent importantes","ok":true,"why":"Elle associe des nodules inflammatoires, avec extension fréquente au tronc surtout chez le garçon."}],"explanation":"Trois formes principales : mixte (la plus commune), rétentionnelle (la plus fréquente à ses débuts) et nodulaire ou conglobata (grave, cicatricielle). La présence de nodules définit la sévérité.","trap":"Ne pas inverser les âges moyens de début : 12 ans chez les filles, 14 ans chez les garçons.","src":"p. 37-38"},{"id":"d111-qcm-105","type":"QRM","rank":"B","objective":"d111-obj-05","tags":["clinique","étiologie"],"difficulty":2,"stem":"Concernant les formes particulières d'acné, quelles propositions sont exactes ?","options":[{"t":"L'acné néonatale est due aux androgènes d'origine maternelle","ok":true,"why":"Elle apparaît sur le visage dès les premières semaines de vie."},{"t":"L'acné néonatale impose un traitement par isotrétinoïne dès les premières semaines","ok":false,"why":"Elle régresse spontanément en quelques semaines."},{"t":"Une acné féminine grave et résistante aux traitements fait suspecter une endocrinopathie","ok":true,"why":"Comme une acné associée à des signes d'hyperandrogénie (hirsutisme, alopécie, troubles des règles)."},{"t":"La cause la plus fréquente d'acné révélant une endocrinopathie est la maladie des ovaires polykystiques","ok":true,"why":"Elle est recherchée par l'échographie abdomino-pelvienne."},{"t":"Des explorations hormonales sont systématiques devant toute acné de l'adolescent","ok":false,"why":"Elles sont justifiées devant une acné évoquant une endocrinopathie (forme féminine grave et résistante, signes d'hyperandrogénie)."}],"explanation":"Acné néonatale : androgènes maternels, régression spontanée. Acné évoquant une endocrinopathie : dosages hormonaux (testostérone libre, 17OH-progestérone, sulfate de DHA, Δ4-androstènedione) et échographie abdomino-pelvienne.","src":"p. 39"},{"id":"d111-qru-102","type":"QRU","rank":"B","objective":"d111-obj-07","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un adolescent présente des papulo-pustules du visage sans aucun comédon ni microkyste. Que peut-on conclure ?","options":[{"t":"Il s'agit d'une acné rétentionnelle","ok":false,"why":"L'acné rétentionnelle est faite de microkystes et de comédons ouverts."},{"t":"Le diagnostic d'acné est éliminé","ok":true,"why":"L'absence de lésions rétentionnelles élimine le diagnostic d'acné ; on évoque une autre folliculite ou une rosacée."},{"t":"Il s'agit d'une acné mixte juvénile","ok":false,"why":"Cette forme comporte des lésions rétentionnelles et inflammatoires."},{"t":"L'acné est confirmée par la présence de pustules","ok":false,"why":"Les pustules ne suffisent pas : sans lésion rétentionnelle, il ne s'agit pas d'une acné."},{"t":"Il s'agit d'une acné nodulaire","ok":false,"why":"Aucune forme d'acné n'existe sans lésion rétentionnelle."}],"explanation":"Sans comédon ni microkyste, ce n'est pas une acné : on pense à une folliculite infectieuse (bactérienne, à Demodex ou à Candida) ou à une rosacée.","src":"p. 40"},{"id":"d111-qcm-106","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant les traitements locaux de l'acné, quelles propositions sont exactes ?","options":[{"t":"L'irritation est le principal facteur limitant des rétinoïdes topiques","ok":true,"why":"Elle impose d'adapter la posologie et le rythme d'application (par exemple un jour sur deux)."},{"t":"Ces traitements s'appliquent de préférence le matin, après la toilette","ok":false,"why":"On les applique le soir : les ultraviolets les détruisent et certains sont photosensibilisants."},{"t":"Le peroxyde de benzoyle est antibactérien, sans résistance bactérienne connue","ok":true,"why":"Il est aussi légèrement comédolytique ; effets secondaires : irritation, phototoxicité, décoloration des vêtements."},{"t":"Les antibiotiques locaux sont recommandés en monothérapie prolongée","ok":false,"why":"Leur activité est modeste et les résistances progressent : on ne les utilise jamais seuls."},{"t":"Un antibiotique local s'associe au peroxyde de benzoyle ou à un rétinoïde","ok":true,"why":"Sur une durée limitée, en raison des résistances bactériennes, notamment aux macrolides."}],"explanation":"Traitements locaux : rétinoïdes (comédolytiques, irritants), peroxyde de benzoyle (antibactérien), antibiotiques locaux (érythromycine, clindamycine) jamais seuls ; application le soir.","src":"p. 40-41"},{"id":"d111-qcm-107","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant les cyclines (doxycycline, lymécycline) dans l'acné, quelles propositions sont exactes ?","options":[{"t":"Elles peuvent être associées à un antibiotique local","ok":false,"why":"Il ne faut jamais associer un antibiotique général à un antibiotique topique."},{"t":"Ce sont les antibiotiques généraux de choix","ok":true,"why":"Les macrolides ne sont utilisés que brièvement quand les cyclines ne peuvent pas être prescrites (femme enceinte, jeune enfant)."},{"t":"Elles sont utilisées en moyenne 3 mois","ok":true,"why":"Au-delà, le risque de résistance bactériologique augmente."},{"t":"Elles exposent à une phototoxicité, surtout avec la doxycycline","ok":true,"why":"C'est, avec les dyschromies dentaires, un des effets secondaires principaux."},{"t":"Elles ne doivent pas être utilisées chez l'enfant de moins de 8 ans","ok":true,"why":"Risque de dyschromies dentaires."}],"explanation":"Cyclines : antibiotique général de choix, 3 mois en moyenne, toujours avec un traitement local mais jamais avec un antibiotique topique ; phototoxicité et dyschromies dentaires (pas avant 8 ans).","src":"p. 41"},{"id":"d111-qru-103","type":"QRU","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":1,"stem":"Quel traitement systémique de l'acné est le seul capable d'induire des guérisons ?","options":[{"t":"La doxycycline","ok":false,"why":"Les cyclines sont le traitement antibiotique de choix, mais leur effet est suspensif."},{"t":"Le gluconate de zinc","ok":false,"why":"Activité essentiellement anti-inflammatoire, inférieure à celle des cyclines."},{"t":"L'isotrétinoïne","ok":true,"why":"C'est le plus puissant des médicaments antiacnéiques ; les autres traitements systémiques sont uniquement suspensifs."},{"t":"La lymécycline","ok":false,"why":"Comme la doxycycline, elle n'a qu'un effet suspensif."},{"t":"L'érythromycine par voie orale","ok":false,"why":"Les macrolides sont réservés aux situations où les cyclines ne peuvent pas être prescrites, et sont suspensifs."}],"explanation":"L'isotrétinoïne est le plus puissant des médicaments sébostatiques et antiacnéiques : elle seule peut guérir, les autres traitements systémiques étant suspensifs.","src":"p. 41"},{"id":"d111-qcm-108","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant l'isotrétinoïne orale dans l'acné, quelles propositions sont exactes ?","options":[{"t":"C'est un inhibiteur non hormonal de la sécrétion sébacée","ok":true,"why":"Elle induit l'apoptose des sébocytes."},{"t":"Elle agit en bloquant les récepteurs aux androgènes","ok":false,"why":"C'est un inhibiteur non hormonal."},{"t":"La dose moyenne est de 0,5 mg/kg/jour jusqu'à une dose cumulée de 120 à 150 mg/kg","ok":true,"why":"Cette dose cumulée est obtenue en 9 à 12 mois de traitement en moyenne."},{"t":"Elle est prescrite en première intention dans toutes les acnés","ok":false,"why":"C'est un traitement de 2e intention, après échec de 3 mois de cyclines, sauf formes très sévères."},{"t":"La dose peut être diminuée à 0,2-0,3 mg/kg/jour dans les formes rétentionnelles","ok":true,"why":"La posologie est adaptée à la forme clinique de l'acné."}],"explanation":"Isotrétinoïne : seule à guérir, 0,5 mg/kg/jour jusqu'à 120-150 mg/kg cumulés (9 à 12 mois), en 2e intention après 3 mois d'échec des cyclines (d'emblée si forme très sévère).","src":"p. 41-42"},{"id":"d111-qcm-109","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement","suivi"],"difficulty":2,"stem":"Une jeune femme de 20 ans débute l'isotrétinoïne pour une acné sévère. Quelles mesures sont à mettre en place ?","options":[{"t":"Une contraception efficace débutée 1 mois avant le traitement","ok":true,"why":"À poursuivre pendant toute la durée du traitement et 1 mois après son arrêt."},{"t":"L'arrêt de la contraception dès la dernière prise du médicament","ok":false,"why":"La contraception se poursuit 1 mois après l'arrêt."},{"t":"Un test de grossesse (β-hCG plasmatiques) chaque mois, le dernier 5 semaines après l'arrêt","ok":true,"why":"Le médicament est tératogène."},{"t":"Un dosage initial puis tous les 3 mois des transaminases, du cholestérol total et des triglycérides","ok":true,"why":"Risque d'élévation des transaminases et d'hyperlipidémie."},{"t":"Une information détaillée et un consentement signé","ok":true,"why":"Signé par la patiente, ou par son représentant légal si elle est mineure."}],"explanation":"Isotrétinoïne chez la femme en âge de procréer : contraception (1 mois avant, jusqu'à 1 mois après), β-hCG mensuels, consentement signé ; bilan hépatique et lipidique initial puis tous les 3 mois.","src":"p. 41-42"},{"id":"d111-qcm-110","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement","complications"],"difficulty":2,"stem":"Concernant les effets indésirables et les précautions de l'isotrétinoïne, quelles propositions sont exactes ?","options":[{"t":"Une sécheresse cutanéo-muqueuse dose-dépendante est possible (chéilite, xérose cutanée, conjonctivite)","ok":true,"why":"Une rhinite sèche peut aussi donner des épistaxis."},{"t":"L'association aux cyclines est recommandée pour limiter les poussées","ok":false,"why":"Elle est contre-indiquée : risque d'hypertension intracrânienne."},{"t":"Le port de lentilles de contact doit être proscrit","ok":true,"why":"La conjonctivite que peut provoquer le médicament fait proscrire les lentilles."},{"t":"L'évacuation préalable des lésions rétentionnelles augmente le risque de poussée inflammatoire","ok":false,"why":"Elle diminue au contraire ce risque."},{"t":"Une exacerbation de l'acné est possible pendant les 4 premières semaines","ok":true,"why":"D'où l'intérêt d'évacuer d'abord les lésions rétentionnelles."}],"explanation":"Sous isotrétinoïne : sécheresse cutanéo-muqueuse (pas de lentilles), poussée possible pendant 4 semaines (évacuer d'abord les lésions rétentionnelles), douleurs ligamentaires, troubles de l'humeur ; jamais de cyclines.","src":"p. 42"},{"id":"d111-qru-104","type":"QRU","rank":"B","objective":"d111-obj-08","tags":["traitement","pièges"],"difficulty":2,"stem":"Quelle est la raison de la contre-indication de l'association isotrétinoïne et cyclines ?","options":[{"t":"Le risque de dyschromies dentaires","ok":false,"why":"Effet secondaire propre aux cyclines (enfant de moins de 8 ans)."},{"t":"Le risque tératogène","ok":false,"why":"Il est propre à l'isotrétinoïne et impose une contraception efficace."},{"t":"Le risque d'hypertension intracrânienne","ok":true,"why":"C'est la raison de cette contre-indication."},{"t":"Le risque d'élévation des transaminases","ok":false,"why":"Effet de l'isotrétinoïne, surveillé par un dosage initial puis tous les 3 mois."},{"t":"Le risque de résistance bactérienne","ok":false,"why":"Il augmente avec les antibiotiques prolongés (cyclines au-delà de 3 mois), pas avec cette association."}],"explanation":"L'association isotrétinoïne et cyclines est contre-indiquée à cause du risque d'hypertension intracrânienne.","src":"p. 42"},{"id":"d111-qru-105","type":"QRU","rank":"B","objective":"d111-obj-09","tags":["traitement"],"difficulty":2,"stem":"Une femme de 19 ans présentant une acné souhaite une contraception œstroprogestative. Quel progestatif privilégier en première intention ?","options":[{"t":"Le norgestimate","ok":false,"why":"Il est recommandé en deuxième intention."},{"t":"Le lévonorgestrel","ok":true,"why":"Progestatif de 2e génération, à faible activité androgénique."},{"t":"Un progestatif à forte activité androgénique","ok":false,"why":"On privilégie des progestatifs à faible activité androgénique."},{"t":"L'acétate de cyprotérone associé à l'éthinylestradiol","ok":false,"why":"Cette association peut être proposée en tenant compte du risque thromboembolique (ANSM), mais pas en première intention ; elle est exclue sous isotrétinoïne."},{"t":"Aucun : les œstroprogestatifs sont contre-indiqués dans l'acné","ok":false,"why":"Avec un besoin contraceptif, on choisit un progestatif peu androgénique ; sans besoin contraceptif, on n'en prescrit pas pour l'acné."}],"explanation":"Contraception œstroprogestative chez une femme acnéique : progestatif peu androgénique, lévonorgestrel en première intention, norgestimate en deuxième intention.","src":"p. 42"},{"id":"d111-qcm-111","type":"QRM","rank":"B","objective":"d111-obj-08","tags":["traitement","suivi"],"difficulty":2,"stem":"Concernant la stratégie thérapeutique de l'acné, quelles propositions sont exactes ?","options":[{"t":"La gravité dépend de l'extension des lésions et du nombre de nodules","ok":true,"why":"Extension : moins de la moitié du visage, plus de la moitié ou tout le visage."},{"t":"Un traitement d'entretien est inutile une fois la rémission obtenue","ok":false,"why":"Un traitement d'entretien local est poursuivi aussi longtemps que nécessaire."},{"t":"Le traitement d'attaque est prescrit 3 mois avant de juger de son efficacité","ok":true,"why":"Les effets du traitement ne sont jamais rapides."},{"t":"L'isotrétinoïne est le traitement de première intention des acnés moyennes","ok":false,"why":"C'est un traitement de 2e intention après échec de 3 mois de cyclines (plus tôt si forme très sévère)."},{"t":"Les topiques suffisent dans les acnés légères","ok":true,"why":"Peroxyde de benzoyle seul ou associé à un rétinoïde ; ils sont associés aux cyclines dans les acnés moyennes et sévères."}],"explanation":"Traitement selon la gravité : topiques seuls si acné légère, cyclines et topiques si acné moyenne ou sévère, isotrétinoïne en 2e intention (d'emblée si très sévère), puis entretien local.","src":"p. 42"},{"id":"d111-qcm-112","type":"QRM","rank":"B","objective":"d111-obj-10","tags":["traitement","prévention"],"difficulty":2,"stem":"Quels conseils donner à un patient acnéique ?","options":[{"t":"Suivre un régime alimentaire strict","ok":false,"why":"Il n'y a pas de régime alimentaire à suivre."},{"t":"Ne pas presser les comédons","ok":true,"why":"Fait partie des conseils de base donnés au patient."},{"t":"Appliquer le traitement local le soir sur tout le visage, et pas seulement sur les lésions","ok":true,"why":"Les ultraviolets détruisent ces produits et certains sont photosensibilisants."},{"t":"Passer un antiseptique sur les lésions et faire une toilette énergique","ok":false,"why":"C'est inutile, voire préjudiciable."},{"t":"Utiliser une crème hydratante le matin si nécessaire","ok":true,"why":"Elle protège la barrière cutanée de l'irritation induite par les topiques."}],"explanation":"Conseils : ne pas presser les comédons, traitement local le soir sur tout le visage, hydratant le matin, ni régime ni antiseptique ; il faut 2 à 3 mois pour un résultat appréciable.","src":"p. 45"},{"id":"d111-qcm-113","type":"QRM","rank":"A","objective":"d111-obj-11","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Une femme de 45 ans, à peau et yeux clairs, consulte pour des poussées de rougeur du visage déclenchées par l'alcool et les aliments épicés. Elle présente un érythème permanent des joues et du nez avec des télangiectasies, sans comédon. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic de rosacée est clinique","ok":true,"why":"Aucun examen complémentaire n'est nécessaire."},{"t":"Une biopsie cutanée est nécessaire pour confirmer le diagnostic","ok":false,"why":"Le diagnostic est clinique, sans examen complémentaire."},{"t":"Les dermocorticoïdes sont contre-indiqués","ok":true,"why":"Ils sont contre-indiqués dans la rosacée."},{"t":"Une atteinte oculaire est possible","ok":true,"why":"Sécheresse, conjonctivite, blépharite, voire kératite peuvent s'observer."},{"t":"Il s'agit d'une acné rosacée","ok":false,"why":"Ce terme ancien doit être abandonné : la rosacée n'est pas une acné."}],"explanation":"Rougeur centrofaciale chronique de l'adulte avec bouffées vasomotrices : diagnostic clinique, dermocorticoïdes contre-indiqués, atteinte oculaire possible.","src":"p. 46, 50"},{"id":"d111-qcm-114","type":"QRM","rank":"A","objective":"d111-obj-11","tags":["clinique"],"difficulty":1,"stem":"Concernant les formes cliniques de la rosacée, quelles propositions sont exactes ?","options":[{"t":"La forme papulo-pustuleuse est la plus caractéristique","ok":true,"why":"Des papules inflammatoires et des pustules apparaissent sur un fond d'érythème permanent."},{"t":"Le passage par ces trois formes successives est obligatoire","ok":false,"why":"Il n'est pas obligatoire."},{"t":"La forme vasculaire comprend des bouffées vasomotrices et un érythème permanent avec télangiectasies","ok":true,"why":"Les bouffées sont des poussées paroxystiques de rougeur du visage et du cou, avec sensation de chaleur."},{"t":"Les comédons sont typiques de la forme papulo-pustuleuse","ok":false,"why":"Les comédons et microkystes manquent dans la rosacée : ils orientent vers l'acné."},{"t":"La forme hypertrophique est le rhinophyma","ok":true,"why":"Le nez augmente de volume, devient rouge puis fibreux."}],"explanation":"Trois formes : vasculaire (flushes, couperose), papulo-pustuleuse (la plus caractéristique) et hypertrophique (rhinophyma), sans passage obligatoire de l'une à l'autre.","src":"p. 46-48"},{"id":"d111-qru-106","type":"QRU","rank":"A","objective":"d111-obj-11","tags":["clinique","épidémiologie"],"difficulty":1,"stem":"Quel est le terrain le plus typique de la rosacée ?","options":[{"t":"Adolescent de 15 ans, avec une peau grasse et luisante","ok":false,"why":"C'est le terrain de l'acné."},{"t":"Nourrisson de 1 mois, en bonne santé","ok":false,"why":"La rosacée touche l'adulte, après 20 ans."},{"t":"Homme de 25 ans, avec des squames grasses du visage","ok":false,"why":"Terrain de la dermatite séborrhéique de l'adulte (homme jeune)."},{"t":"Femme de 45 ans, à peau, yeux et cheveux clairs","ok":true,"why":"La rosacée prédomine chez la femme (F/H environ 2), avec un pic entre 40 et 50 ans, sur peau, yeux et cheveux clairs."},{"t":"Sujet à peau foncée, sans prédominance de sexe","ok":false,"why":"La rosacée touche surtout les peaux claires et prédomine chez la femme."}],"explanation":"Rosacée : adulte après 20 ans, pic à 40-50 ans, prédominance féminine, peau, yeux et cheveux clairs.","src":"p. 46"},{"id":"d111-qru-107","type":"QRU","rank":"A","objective":"d111-obj-12","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Un homme de 62 ans, qui ne consomme pas d'alcool, présente un nez augmenté de volume, diffusément rouge, avec des orifices folliculaires dilatés et une peau épaissie. Quel est le diagnostic ?","options":[{"t":"Les séquelles d'un alcoolisme chronique","ok":false,"why":"Le nez en « trogne » du rhinophyma survient sans qu'un alcoolisme soit en cause."},{"t":"Une acné nodulaire du nez","ok":false,"why":"L'acné associe des lésions rétentionnelles et inflammatoires, sans hypertrophie du nez avec orifices dilatés."},{"t":"Une couperose (rosacée érythémato-télangiectasique)","ok":false,"why":"Forme vasculaire : érythème permanent avec télangiectasies, sans hypertrophie."},{"t":"Une dermatite séborrhéique du nez","ok":false,"why":"Elle donne des plaques érythémateuses à squames grasses (ailes du nez, sillons nasogéniens)."},{"t":"Un rhinophyma (rosacée hypertrophique)","ok":true,"why":"Forme hypertrophique de la rosacée, surtout chez l'homme de plus de 50 ans, à l'aspect de « trogne »."}],"explanation":"Nez volumineux, rouge, orifices folliculaires dilatés, peau épaissie chez l'homme de plus de 50 ans : rhinophyma, forme hypertrophique de la rosacée, sans lien nécessaire avec l'alcool.","src":"p. 48"},{"id":"d111-qcm-115","type":"QRM","rank":"A","objective":"d111-obj-11","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Devant une éruption papulo-pustuleuse du visage chez l'adulte, quels éléments orientent vers une rosacée plutôt que vers une acné ?","options":[{"t":"Une séborrhée constante","ok":false,"why":"La séborrhée est un signe d'acné."},{"t":"La présence de bouffées vasomotrices","ok":true,"why":"Elles manquent dans l'acné."},{"t":"L'absence de comédons et de microkystes","ok":true,"why":"Les signes rétentionnels caractérisent l'acné."},{"t":"Une prédominance masculine nette","ok":false,"why":"La rosacée prédomine chez la femme (F/H environ 2)."},{"t":"Un terrain d'adulte d'âge moyen","ok":true,"why":"Le terrain diffère : l'acné touche plutôt le sujet jeune, la rosacée l'adulte (pic à 40-50 ans)."}],"explanation":"Rosacée : bouffées vasomotrices, ni comédons ni microkystes, adulte d'âge moyen. Acné : signes rétentionnels, séborrhée, sujet jeune.","src":"p. 46, 48"},{"id":"d111-qcm-116","type":"QRM","rank":"A","objective":"d111-obj-14","tags":["clinique","épidémiologie"],"difficulty":1,"stem":"Concernant la dermatite séborrhéique de l'adulte, quelles propositions sont exactes ?","options":[{"t":"Elle touche le plus souvent l'homme jeune (18 à 40 ans)","ok":true,"why":"C'est son terrain le plus fréquent."},{"t":"Elle est contagieuse","ok":false,"why":"Il n'y a pas de contagiosité : ce n'est pas une maladie infectieuse à proprement parler."},{"t":"Elle est aggravée par les stress émotionnels","ok":true,"why":"Les poussées sont parfois favorisées par le stress et les contrariétés."},{"t":"Le diagnostic repose sur un prélèvement mycologique","ok":false,"why":"Le diagnostic est clinique, sans biopsie ni examen biologique ou mycologique."},{"t":"Elle s'améliore spontanément en été","ok":true,"why":"C'est une évolution classique de la forme de l'adulte."}],"explanation":"Dermatite séborrhéique de l'adulte : homme jeune, aggravée par le stress, améliorée l'été, non contagieuse, diagnostic clinique.","src":"p. 50-51"},{"id":"d111-qcm-117","type":"QRM","rank":"A","objective":"d111-obj-15","tags":["clinique"],"difficulty":2,"stem":"Quelles localisations peuvent être atteintes par la dermatite séborrhéique ?","options":[{"t":"Les paumes et les plantes","ok":false,"why":"La dermatite séborrhéique touche de manière sélective les zones séborrhéiques de la tête et du tronc."},{"t":"Les sillons nasogéniens et les sourcils","ok":true,"why":"Ce sont des zones où prédomine la séborrhée."},{"t":"La glabelle et la lisière antérieure du cuir chevelu","ok":true,"why":"Le visage est la localisation la plus fréquente."},{"t":"La face antérieure des jambes","ok":false,"why":"Ce n'est pas une zone séborrhéique."},{"t":"La région présternale","ok":true,"why":"Plaques annulaires ou circinées à bordure squameuse sur le tronc."}],"explanation":"Visage (sillons nasogéniens, sourcils, glabelle, lisière du cuir chevelu, barbe, bords ciliaires), cuir chevelu, région présternale, zones pileuses et génitales : toujours des zones séborrhéiques.","src":"p. 51-52"},{"id":"d111-qcm-118","type":"QRM","rank":"A","objective":"d111-obj-14","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Concernant la dermatite séborrhéique du nouveau-né et du nourrisson, quelles propositions sont exactes ?","options":[{"t":"Elle débute après la deuxième semaine de vie","ok":true,"why":"Elle survient chez des nouveau-nés en bonne santé."},{"t":"Elle survient surtout chez des nouveau-nés immunodéprimés","ok":false,"why":"Elle débute chez des nouveau-nés en bonne santé."},{"t":"La forme typique réalise des croûtes jaunes du cuir chevelu (croûtes de lait)","ok":true,"why":"Le visage peut aussi être atteint, ainsi que le siège et les plis axillaires."},{"t":"Une forme étendue peut réaliser l'érythrodermie de Leiner-Moussous","ok":true,"why":"C'est la forme étendue et extensive de la maladie chez le nourrisson."},{"t":"L'érythrodermie de Leiner-Moussous a le plus souvent une évolution défavorable","ok":false,"why":"Son évolution est le plus souvent spontanément favorable."}],"explanation":"Chez le nourrisson : début après la 2e semaine, croûtes de lait, atteinte possible du siège et des plis, forme étendue = érythrodermie de Leiner-Moussous d'évolution le plus souvent favorable.","src":"p. 52"},{"id":"d111-qcm-119","type":"QRM","rank":"B","objective":"d111-obj-16","tags":["diagnostic"],"difficulty":2,"stem":"Concernant le diagnostic différentiel de la dermatite séborrhéique, quelles propositions sont exactes ?","options":[{"t":"Le psoriasis des régions séborrhéiques (sébopsoriasis) est souvent impossible à différencier cliniquement","ok":true,"why":"Les localisations extrafaciales et les antécédents permettent de séparer les deux entités."},{"t":"Une biopsie cutanée est nécessaire pour trancher entre dermatite séborrhéique et psoriasis","ok":false,"why":"Le diagnostic repose sur l'examen clinique, sans biopsie : ce sont les localisations extrafaciales et les antécédents qui séparent les deux entités."},{"t":"Chez le nourrisson, l'érythrodermie de Leiner-Moussous pourrait être un mode de début d'une dermatite atopique ou d'un psoriasis","ok":true,"why":"C'est un point de vigilance chez le nourrisson."},{"t":"La dermatite atopique reste toujours strictement limitée aux zones séborrhéiques","ok":false,"why":"Elle déborde largement les localisations typiques des régions séborrhéiques."},{"t":"Chez l'adulte, une dermatite atopique limitée à la tête et au cou peut prêter à confusion","ok":true,"why":"Elle déborde toutefois largement les localisations typiques des régions séborrhéiques."}],"explanation":"Les principaux diagnostics différentiels de la dermatite séborrhéique sont le psoriasis (sébopsoriasis) et la dermatite atopique ; les localisations extrafaciales et les antécédents aident à trancher.","src":"p. 52"},{"id":"d111-qru-108","type":"QRU","rank":"A","objective":"d111-obj-14","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un homme de 38 ans présente depuis plusieurs années une dermatite séborrhéique profuse du visage et du tronc, résistante aux traitements. Quelle attitude est recommandée ?","options":[{"t":"Réaliser une biopsie cutanée pour confirmer le diagnostic","ok":false,"why":"Le diagnostic est clinique, sans biopsie."},{"t":"Doser la testostérone libre","ok":false,"why":"Les explorations hormonales concernent l'acné évoquant une endocrinopathie, pas la dermatite séborrhéique."},{"t":"Proposer un test de dépistage du VIH","ok":true,"why":"Une dermatite séborrhéique grave et/ou chronique doit y conduire ; les formes profuses résistantes sont fréquentes au cours du VIH."},{"t":"Réaliser un prélèvement mycologique pour confirmer le diagnostic","ok":false,"why":"Le diagnostic est clinique, sans examen biologique ou mycologique."},{"t":"Débuter une isotrétinoïne","ok":false,"why":"C'est un traitement de l'acné ; la dermatite séborrhéique relève essentiellement d'un traitement local antifongique."}],"explanation":"Une dermatite séborrhéique grave et/ou chronique, profuse et résistante, doit faire proposer un dépistage du VIH ; le diagnostic reste clinique.","src":"p. 51-53"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d111-pareto","points":[{"id":"d111-par-01","rank":"A","cat":"définition","text":"**Acné** = dermatose inflammatoire chronique du **follicule pilo-sébacé**, surtout à l'adolescence ; diagnostic **clinique**","src":"p. 34-35, 45"},{"id":"d111-par-02","rank":"A","cat":"clinique","text":"Lésions : **rétentionnelles** (comédons ouverts = points noirs, fermés = microkystes) ; inflammatoires : papules **< 10 mm**, pustules, **nodules > 10 mm** → cicatrices","src":"p. 35-37"},{"id":"d111-par-03","rank":"B","cat":"piège","text":"Isotrétinoïne = **tératogène** : contraception **1 mois avant → 1 mois après**, test de grossesse **mensuel** (dernier 5 sem après l'arrêt), consentement signé","src":"p. 41-42"},{"id":"d111-par-04","rank":"B","cat":"traitement","text":"Isotrétinoïne : seule à guérir ; **120-150 mg/kg** cumulés (0,5 mg/kg/j) ; **2e intention** après 3 mois de cyclines ; jamais avec les **cyclines** (HTIC) ; bilan hépatique + lipides /3 mois","src":"p. 41-42"},{"id":"d111-par-05","rank":"A","cat":"définition","text":"**Rosacée** = rougeur **centrofaciale** chronique de l'adulte (40-50 ans, femme, peau claire) avec **bouffées vasomotrices** ; diagnostic clinique, **aucun examen**","src":"p. 46, 50"},{"id":"d111-par-06","rank":"A","cat":"clinique","text":"3 formes : **vasculaire** (flushes, érythème + télangiectasies = couperose), **papulo-pustuleuse** (la plus caractéristique), **hypertrophique** (rhinophyma)","src":"p. 46-48"},{"id":"d111-par-07","rank":"A","cat":"piège","text":"Rosacée : **dermocorticoïdes contre-indiqués** ; ni comédons ni microkystes (≠ acné) ; **atteinte oculaire** possible ; chronique par poussées","src":"p. 48, 50"},{"id":"d111-par-08","rank":"A","cat":"clinique","text":"**Dermatite séborrhéique** : dermatose chronique fréquente (**Malassezia** suspectée, non contagieuse) ; plaques érythémateuses à **squames grasses** (sillons nasogéniens, sourcils, glabelle) ; diagnostic **clinique**","src":"p. 50-51"},{"id":"d111-par-09","rank":"A","cat":"clinique","text":"DS du nourrisson : après la 2e semaine, **croûtes de lait** ; forme étendue = érythrodermie de **Leiner-Moussous** (évolution favorable) ; DS de l'adulte : homme jeune, stress","src":"p. 51-52"},{"id":"d111-par-10","rank":"A","cat":"piège","text":"DS sévère : Parkinson, alcoolisme chronique, carcinomes des VADS, VIH ; DS grave et/ou chronique → **dépistage du VIH** ; traitement essentiellement **local antifongique**","src":"p. 52-53"},{"id":"d111-par-11","rank":"A","cat":"clinique","text":"**Rhinophyma** : homme (> 95 %), > **50 ans**, nez volumineux rouge fibreux à orifices dilatés, **sans alcoolisme** ; passage par les 3 formes non obligatoire","src":"p. 48"},{"id":"d111-par-12","rank":"B","cat":"traitement","text":"Local : **rétinoïdes** (comédolytiques, irritation), **peroxyde de benzoyle** (antibactérien), ATB locaux **jamais seuls**, application le **soir** ; ATB oral : **cyclines** ~3 mois","src":"p. 40-41"},{"id":"d111-par-13","rank":"B","cat":"gravité","text":"Gravité de l'acné = **étendue** + **nombre de nodules** ; sans comédon = **pas d'acné** ; acné féminine grave résistante ou avec hirsutisme → **endocrinopathie**","src":"p. 39-40, 42"},{"id":"d111-par-14","rank":"B","cat":"traitement","text":"Contraception d'une acnéique : **lévonorgestrel** en 1re intention, **norgestimate** en 2e ; cyprotérone/EE jamais sous isotrétinoïne ; **pas de régime** alimentaire","src":"p. 42, 45"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
